import heapq
import os
from typing import Dict, List

import networkx as nx
import pandas as pd


def search_algorithm(src, dsts, G, num_partitions):
    """Construct a source-rooted, low edge-union-cost broadcast topology."""
    topology = BroadCastTopology(src, dsts, num_partitions)
    unique_dsts = list(dict.fromkeys(dsts))
    if not unique_dsts or src not in G:
        return topology

    h = G.copy()
    h.remove_edges_from(list(h.in_edges(src)) + list(nx.selfloop_edges(h)))

    bad = []
    for u, v, data in h.edges(data=True):
        try:
            if data.get("cost") is None or float(data["cost"]) < 0:
                bad.append((u, v))
        except (TypeError, ValueError):
            bad.append((u, v))
    h.remove_edges_from(bad)

    def edge_path(nodes):
        return tuple(zip(nodes, nodes[1:]))

    try:
        lengths, base_node_paths = nx.single_source_dijkstra(h, src, weight="cost")
    except (nx.NetworkXNoPath, nx.NodeNotFound):
        lengths, base_node_paths = {}, {}

    reachable = [d for d in unique_dsts if d in lengths]
    terminals = [d for d in reachable if d != src]

    def project(active):
        sub = nx.DiGraph()
        for u, v in active:
            if h.has_edge(u, v):
                sub.add_edge(u, v, **h[u][v])

        result = {}
        if src in reachable:
            result[src] = tuple()
        if src not in sub:
            return result

        try:
            _, node_paths = nx.single_source_dijkstra(sub, src, weight="cost")
        except (nx.NetworkXNoPath, nx.NodeNotFound):
            return result

        for dst in reachable:
            if dst != src and dst in node_paths:
                result[dst] = edge_path(node_paths[dst])
        return result

    def exact_steiner():
        """Dreyfus-Wagner DP for a bounded number of directed terminals."""
        k = len(terminals)
        if k == 0:
            return {src: tuple()}
        # The additional terminal relative to the parent remains a tightly
        # bounded exponential solve, while avoiding a premature greedy cutoff.
        if k > 11:
            return None

        rev = h.reverse(copy=False)
        full = (1 << k) - 1
        dp = {}
        choice = {}

        for i, terminal in enumerate(terminals):
            mask = 1 << i
            try:
                dist, reverse_paths = nx.single_source_dijkstra(
                    rev, terminal, weight="cost"
                )
            except (nx.NetworkXNoPath, nx.NodeNotFound):
                return None

            dp[mask] = {node: float(value) for node, value in dist.items()}
            picks = {}
            for node, rpath in reverse_paths.items():
                picks[node] = ("base", edge_path(list(reversed(rpath))))
            choice[mask] = picks

        for mask in range(1, full + 1):
            if mask in dp:
                continue

            values = {}
            picks = {}
            submask = (mask - 1) & mask
            while submask:
                other = mask ^ submask
                if other and submask < other:
                    left = dp[submask]
                    right = dp[other]
                    for node in set(left).intersection(right):
                        value = left[node] + right[node]
                        if value + 1e-12 < values.get(node, float("inf")):
                            values[node] = value
                            picks[node] = ("split", submask, other)
                submask = (submask - 1) & mask

            if not values:
                return None

            heap = []
            serial = 0
            for node, value in values.items():
                heapq.heappush(heap, (value, serial, node))
                serial += 1

            while heap:
                value, _, node = heapq.heappop(heap)
                if value != values.get(node):
                    continue
                for pred in h.predecessors(node):
                    candidate = value + float(h[pred][node]["cost"])
                    if candidate + 1e-12 < values.get(pred, float("inf")):
                        values[pred] = candidate
                        picks[pred] = ("edge", node)
                        heapq.heappush(heap, (candidate, serial, pred))
                        serial += 1

            dp[mask] = values
            choice[mask] = picks

        if src not in dp[full]:
            return None

        active = set()
        visiting = set()

        def recover(mask, node):
            key = (mask, node)
            if key in visiting:
                return
            visiting.add(key)
            item = choice[mask].get(node)
            if item is not None:
                if item[0] == "base":
                    active.update(item[1])
                elif item[0] == "split":
                    recover(item[1], node)
                    recover(item[2], node)
                else:
                    nxt = item[1]
                    active.add((node, nxt))
                    recover(mask, nxt)
            visiting.remove(key)

        recover(full, src)
        result = project(active)
        return result if all(dst in result for dst in reachable) else None

    def greedy_union():
        """Deterministic multi-order marginal union routing for large instances."""
        if not reachable:
            return {}

        orders = [
            sorted(reachable, key=lambda d: (lengths[d], str(d))),
            sorted(reachable, key=lambda d: (-lengths[d], str(d))),
            list(reachable),
        ]
        unique_orders = []
        for order in orders:
            if order not in unique_orders:
                unique_orders.append(order)

        best_paths = {}
        best_cost = float("inf")

        for order in unique_orders:
            counts = {}
            routes = {}

            def marginal(u, v, data):
                return 0.0 if (u, v) in counts else float(data["cost"])

            for dst in order:
                if dst == src:
                    routes[dst] = tuple()
                    continue
                try:
                    route = edge_path(nx.dijkstra_path(h, src, dst, weight=marginal))
                except (nx.NetworkXNoPath, nx.NodeNotFound):
                    continue
                routes[dst] = route
                for edge in route:
                    counts[edge] = counts.get(edge, 0) + 1

            for _ in range(3):
                changed = False
                for dst in order:
                    if dst == src or dst not in routes:
                        continue
                    old = routes[dst]
                    for edge in old:
                        counts[edge] -= 1
                        if counts[edge] == 0:
                            del counts[edge]
                    try:
                        new = edge_path(nx.dijkstra_path(h, src, dst, weight=marginal))
                    except (nx.NetworkXNoPath, nx.NodeNotFound):
                        new = old
                    routes[dst] = new
                    changed = changed or new != old
                    for edge in new:
                        counts[edge] = counts.get(edge, 0) + 1
                if not changed:
                    break

            projected = project(counts)
            if not all(dst in projected for dst in reachable):
                projected = routes

            union = {
                edge
                for route in projected.values()
                for edge in route
            }
            cost = sum(float(h[u][v]["cost"]) for u, v in union)
            if cost < best_cost:
                best_cost = cost
                best_paths = projected

        return best_paths

    best_paths = exact_steiner()
    if best_paths is None:
        best_paths = greedy_union()

    for dst in unique_dsts:
        route = best_paths.get(dst)
        if route is None:
            continue
        edges = [[u, v, G[u][v]] for u, v in route]
        for partition in range(topology.num_partitions):
            topology.set_dst_partition_paths(dst, partition, list(edges))

    return topology


class SingleDstPath(Dict):
    partition: int
    edges: List[List]


class BroadCastTopology:
    def __init__(
        self,
        src: str,
        dsts: List[str],
        num_partitions: int = 4,
        paths: Dict[str, SingleDstPath] = None,
    ):
        self.src = src
        self.dsts = dsts
        self.num_partitions = num_partitions
        if paths is not None:
            self.paths = paths
            self.set_graph()
        else:
            self.paths = {
                dst: {str(i): None for i in range(num_partitions)}
                for dst in dsts
            }

    def get_paths(self):
        print(f"now the set path is: {self.paths}")
        return self.paths

    def set_num_partitions(self, num_partitions: int):
        self.num_partitions = num_partitions

    def set_dst_partition_paths(self, dst: str, partition: int, paths: List[List]):
        self.paths[dst][str(partition)] = paths

    def append_dst_partition_path(self, dst: str, partition: int, path: List):
        partition = str(partition)
        if self.paths[dst][partition] is None:
            self.paths[dst][partition] = []
        self.paths[dst][partition].append(path)


def make_nx_graph(cost_path=None, throughput_path=None, num_vms=1):
    current_dir = os.path.dirname(os.path.abspath(__file__))
    cost = pd.read_csv(
        os.path.join(current_dir, "profiles/cost.csv")
        if cost_path is None else cost_path
    )
    throughput = pd.read_csv(
        os.path.join(current_dir, "profiles/throughput.csv")
        if throughput_path is None else throughput_path
    )

    G = nx.DiGraph()
    for _, row in throughput.iterrows():
        if row["src_region"] == row["dst_region"]:
            continue
        G.add_edge(
            row["src_region"],
            row["dst_region"],
            cost=None,
            throughput=num_vms * row["throughput_sent"] / 1e9,
        )

    for _, row in cost.iterrows():
        if row["src"] in G and row["dest"] in G[row["src"]]:
            G[row["src"]][row["dest"]]["cost"] = row["cost"]

    no_cost_pairs = [
        (u, v)
        for u, v, data in G.edges(data=True)
        if data.get("cost") is None
    ]
    print("Unable to get costs for: ", no_cost_pairs)
    return G


